{
  "items": [
    {
      "name": "Finsupp.finite_of_nat_weight_le",
      "module_name": "Mathlib.Data.Finsupp.Weight",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} [Finite σ] (w : σ → ℕ), (∀ (x : σ), w x ≠ 0) → ∀ (n : ℕ), {d | (Finsupp.weight w) d ≤ n}.Finite"
    },
    {
      "name": "AddMonoidHom.map_finsum_mem'",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} {N : Type u_6} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {s : Set α}\n  {f : α → M} (g : M →+ N),\n  (s ∩ Function.support f).Finite → g (∑ᶠ (j : α) (_ : j ∈ s), f j) = ∑ᶠ (i : α) (_ : i ∈ s), g (f i)"
    },
    {
      "name": "map_dfinsuppSum",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] {R : Type u_1} {S : Type u_2} {H : Type u_3}\n  [inst_1 : (i : ι) → Zero (β i)] [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_3 : AddCommMonoid R]\n  [inst_4 : AddCommMonoid S] [inst_5 : FunLike H R S] [AddMonoidHomClass H R S] (h : H) (f : Π₀ (i : ι), β i)\n  (g : (i : ι) → β i → R), h (f.sum g) = f.sum fun a b => h (g a b)"
    },
    {
      "name": "map_finsum",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_5} {N : Type u_6} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] {f : α → M}\n  {G : Type u_7} [inst_2 : FunLike G M N] [AddMonoidHomClass G M N] (g : G),\n  (Function.support f).Finite → g (∑ᶠ (i : α), f i) = ∑ᶠ (i : α), g (f i)"
    },
    {
      "name": "AddMonoidHom.map_finsum_plift",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {N : Type u_3} {α : Sort u_4} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N] (f : M →+ N)\n  (g : α → M), (Function.support (g ∘ PLift.down)).Finite → f (∑ᶠ (x : α), g x) = ∑ᶠ (x : α), f (g x)"
    },
    {
      "name": "AddMonoidHom.map_dfinsuppSumAddHom",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] {R : Type u_1} {S : Type u_2} [inst_1 : AddCommMonoid R]\n  [inst_2 : AddCommMonoid S] [inst_3 : (i : ι) → AddZeroClass (β i)] (h : R →+ S) (f : Π₀ (i : ι), β i)\n  (g : (i : ι) → β i →+ R), h ((DFinsupp.sumAddHom g) f) = (DFinsupp.sumAddHom fun i => h.comp (g i)) f"
    },
    {
      "name": "map_finsuppSum",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} {P : Type u_11} [inst : Zero M] [inst_1 : AddCommMonoid N]\n  [inst_2 : AddCommMonoid P] {H : Type u_16} [inst_3 : FunLike H N P] [AddMonoidHomClass H N P] (h : H) (f : α →₀ M)\n  (g : α → M → N), h (f.sum g) = f.sum fun a b => h (g a b)"
    },
    {
      "name": "Finsupp.sum_mapDomain_index",
      "module_name": "Mathlib.Data.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {M : Type u_5} {N : Type u_6} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N]\n  {f : α → β} {s : α →₀ M} {h : β → M → N},\n  (∀ (b : β), h b 0 = 0) →\n    (∀ (b : β) (m₁ m₂ : M), h b (m₁ + m₂) = h b m₁ + h b m₂) →\n      (Finsupp.mapDomain f s).sum h = s.sum fun a m => h (f a) m"
    }
  ]
}

